<?php
declare(strict_types=1);
require __DIR__.'/includes/cms-boot.php';
use App\Db;use App\Lunch;
if($_SERVER['REQUEST_METHOD']==='POST'){cms_csrf();try{
 $action=$_POST['action']??'';
 if($action==='add'){$name=trim((string)($_POST['name']??''));$category=trim((string)($_POST['category']??''));if(mb_strlen($name)<2||mb_strlen($name)>140||mb_strlen($category)<2||mb_strlen($category)>80)throw new DomainException('Nome ou categoria inválidos');$q=Db::pdo()->prepare('INSERT INTO daily_menu_items(name,category,by_weight) VALUES(?,?,?)');$q->execute([$name,$category,isset($_POST['by_weight'])?1:0]);Lunch::touchMenu();cms_notice('Item adicionado ao cardápio do dia.');}
 elseif($action==='toggle'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id)throw new DomainException('Item inválido');$q=Db::pdo()->prepare('UPDATE daily_menu_items SET active=NOT active WHERE id=?');$q->execute([$id]);Lunch::touchMenu();cms_notice('Disponibilidade atualizada.');}
 elseif($action==='edit'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$name=trim((string)($_POST['name']??''));$category=trim((string)($_POST['category']??''));if(!$id||mb_strlen($name)<2||mb_strlen($name)>140||mb_strlen($category)<2||mb_strlen($category)>80)throw new DomainException('Prato ou categoria inválidos');$q=Db::pdo()->prepare('UPDATE daily_menu_items SET name=?,category=?,by_weight=? WHERE id=?');$q->execute([$name,$category,isset($_POST['by_weight'])?1:0,$id]);Lunch::touchMenu();cms_notice('Prato atualizado em todas as páginas.');}
 elseif($action==='settings'){$price=filter_var($_POST['price_cents']??null,FILTER_VALIDATE_INT);$max=filter_var($_POST['max_choices']??null,FILTER_VALIDATE_INT);if(!$price||$price<100||$price>100000||!$max||$max>30)throw new DomainException('Preço ou limite inválidos');$q=Db::pdo()->prepare('UPDATE lunch_settings SET price_cents=?,max_choices=?,orders_enabled=? WHERE id=1');$q->execute([$price,$max,isset($_POST['orders_enabled'])?1:0]);cms_notice('Regras do cardápio salvas.');}
 elseif($action==='paid'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id)throw new DomainException('Pedido inválido');$q=Db::pdo()->prepare("UPDATE lunch_orders SET payment_status='paid' WHERE id=? AND payment_status='pending' AND status<>'cancelled'");$q->execute([$id]);if(!$q->rowCount())throw new DomainException('Não foi possível registrar o pagamento');cms_notice('Pagamento recebido e registrado.');}
 elseif($action==='status'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');if(!$id||!in_array($status,['pending','accepted','preparing','out_for_delivery','delivered','cancelled'],true))throw new DomainException('Status inválido');$q=Db::pdo()->prepare('UPDATE lunch_orders SET status=? WHERE id=?');$q->execute([$status,$id]);cms_notice('Status do pedido atualizado.');}
 else throw new DomainException('Ação inválida');
 }catch(Throwable $e){error_log((string)$e);cms_notice($e instanceof DomainException?$e->getMessage():'Erro ao salvar','danger');}}
$s=Lunch::settings();$items=Db::pdo()->query('SELECT * FROM daily_menu_items ORDER BY active DESC,sort_order,id')->fetchAll();$menuDate=Lunch::menuDate();$orders=Db::pdo()->query('SELECT * FROM lunch_orders ORDER BY id DESC LIMIT 40')->fetchAll();$details=[];if($orders){$ids=array_column($orders,'id');$placeholders=implode(',',array_fill(0,count($ids),'?'));$q=Db::pdo()->prepare('SELECT b.order_id,b.box_number,c.item_name FROM lunch_order_boxes b JOIN lunch_order_choices c ON c.box_id=b.id WHERE b.order_id IN ('.$placeholders.') ORDER BY b.order_id,b.box_number,c.id');$q->execute($ids);foreach($q->fetchAll() as $row)$details[(int)$row['order_id']][(int)$row['box_number']][]=$row['item_name'];}
adm_start('Quentinhas','lunch');cms_feedback();?>
<div class="mb-4"><span class="page-kicker">OPERAÇÃO</span><h1 class="page-title">Quentinhas e cardápio do dia</h1><p class="page-subtitle">Atualize pratos e disponibilidade. Se não fizer alterações, o último cardápio continua valendo. Última atualização: <?=adm_h($menuDate)?>.</p></div>
<div class="row g-4 mb-4"><div class="col-lg-5"><section class="content-card p-4"><h2 class="h5">Configurar pedidos</h2><form method="post"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="settings"><label class="form-label">Preço da quentinha (centavos)</label><input class="form-control mb-3" type="number" min="100" name="price_cents" value="<?=adm_h($s['price_cents'])?>" required><label class="form-label">Máximo de escolhas por quentinha</label><input class="form-control mb-3" type="number" min="1" max="30" name="max_choices" value="<?=adm_h($s['max_choices'])?>" required><label class="mb-3 d-block"><input type="checkbox" name="orders_enabled" <?=$s['orders_enabled']?'checked':''?>> Aceitar pedidos online</label><button class="btn btn-bia">Salvar configurações</button></form></section></div><div class="col-lg-7"><section class="content-card p-4"><h2 class="h5">Adicionar item ao cardápio</h2><form method="post"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="add"><label class="form-label">Nome do item</label><input class="form-control mb-3" name="name" placeholder="Ex.: Arroz branco" maxlength="140" required><label class="form-label">Categoria</label><input class="form-control mb-3" name="category" placeholder="Ex.: Acompanhamentos" maxlength="80" required><label class="d-block mb-3"><input type="checkbox" name="by_weight"> Vendido somente por peso (não entra na quentinha)</label><button class="btn btn-bia">Adicionar item</button></form></section></div></div>
<section class="content-card mb-4"><div class="content-heading"><h2>Cardápio publicado</h2><p>Edite qualquer prato, marque os vendidos por peso ou desative opções indisponíveis.</p></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Prato e categoria</th><th>Tipo</th><th>Disponibilidade</th><th>Salvar</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><form method="post" id="menu-item-<?=adm_h($item['id'])?>"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=adm_h($item['id'])?>"><label class="form-label small">Nome</label><input class="form-control mb-2" name="name" maxlength="140" value="<?=adm_h($item['name'])?>" required><label class="form-label small">Categoria</label><select class="form-select" name="category"><?php foreach(['Acompanhamentos','Carnes','Saladas','Tortas e assados'] as $category):?><option value="<?=adm_h($category)?>" <?=$item['category']===$category?'selected':''?>><?=adm_h($category)?></option><?php endforeach;?></select></form></td><td><label class="small"><input type="checkbox" form="menu-item-<?=adm_h($item['id'])?>" name="by_weight" <?=$item['by_weight']?'checked':''?>> Somente por peso (*)</label></td><td><?=($item['active']?'Disponível':'Oculto')?><form method="post" class="mt-2"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=adm_h($item['id'])?>"><button class="btn btn-outline-secondary btn-sm"><?=$item['active']?'Desativar':'Ativar'?></button></form></td><td><button class="btn btn-bia btn-sm" form="menu-item-<?=adm_h($item['id'])?>">Salvar prato</button></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="content-card"><div class="content-heading"><h2>Pedidos recentes</h2></div><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Cliente / endereço</th><th>Quentinhas</th><th>Valor</th><th>Pagamento</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=adm_h($o['id'])?></td><td><?=adm_h($o['customer_name'])?><br><small><?=adm_h($o['address'])?>, <?=adm_h($o['neighborhood'])?><br>Referência: <?=adm_h($o['reference_point'])?><br><?=adm_h($o['customer_phone'])?></small></td><td><strong><?=adm_h($o['quantity'])?></strong><?php foreach(($details[(int)$o['id']]??[]) as $number=>$choices):?><div class="small text-secondary mt-2"><strong>Quentinha <?=adm_h($number)?>:</strong> <?=adm_h(implode(', ',$choices))?></div><?php endforeach;?></td><td>R$ <?=number_format($o['total_cents']/100,2,',','.')?></td><td><?=adm_h($o['payment_method']==='pix'?'Pix':'Cartão')?> · <?=adm_h($o['payment_status']==='paid'?'Pago':'Pendente')?><?php if($o['payment_status']==='pending'&&$o['status']!=='cancelled'):?><form method="post" class="mt-2" onsubmit="return confirm('O pagamento foi realmente recebido?')"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="paid"><input type="hidden" name="id" value="<?=adm_h($o['id'])?>"><button class="btn btn-outline-secondary btn-sm">Confirmar recebimento</button></form><?php endif;?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=adm_h($csrf)?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=adm_h($o['id'])?>"><select class="form-select" name="status"><?php foreach(['pending'=>'Pendente','accepted'=>'Aceito','preparing'=>'Preparando','out_for_delivery'=>'Em entrega','delivered'=>'Entregue','cancelled'=>'Cancelado'] as $key=>$value):?><option value="<?=$key?>" <?=$o['status']===$key?'selected':''?>><?=$value?></option><?php endforeach;?></select><button class="btn btn-bia btn-sm mt-2">Atualizar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php adm_end();